const tabs = await (await fetch('http://127.0.0.1:9222/json')).json();
const tab = tabs.find((item) => item.url === 'http://127.0.0.1:8766/');
const socket = new WebSocket(tab.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data);
  if (message.method === 'Runtime.exceptionThrown') console.log('EXCEPTION', message.params.exceptionDetails.text, message.params.exceptionDetails.exception?.description);
  if (message.method === 'Runtime.consoleAPICalled') console.log('CONSOLE', message.params.type, message.params.args.map((arg) => arg.value ?? arg.description).join(' '));
  if (message.id && pending.has(message.id)) { pending.get(message.id)(message); pending.delete(message.id); }
});
await new Promise((resolve) => socket.addEventListener('open', resolve, { once: true }));
const send = (method, params = {}) => new Promise((resolve) => { const requestId = ++id; pending.set(requestId, resolve); socket.send(JSON.stringify({ id: requestId, method, params })); });
await send('Runtime.enable');
await send('Page.reload', { ignoreCache: true });
await new Promise((resolve) => setTimeout(resolve, 6000));
const result = await send('Runtime.evaluate', { expression: "({ready:document.readyState,canvas:document.querySelectorAll('canvas').length,intro:document.querySelector('#intro')?.className})", returnByValue: true });
console.log('PAGE', JSON.stringify(result.result?.result?.value ?? result.result));
socket.close();
